-- Achievements and awards

create table "public"."achievements" (
  "id" bigint primary key generated by default as identity,
  "image" varchar,
  "name" varchar,
  "description" text,
  "issuer" varchar,
  "date" date,
  "user" uuid,
  "order" smallint,
  "is_active" boolean not null default true
);

alter table "public"."achievements" add constraint "achievements_user_fkey" foreign key ("user") references auth.users (id) on update cascade on delete cascade;

alter table "public"."achievements" enable row level security;
create policy "Enable read access for all users" on "public"."achievements" for select using (true);

grant all on "public"."achievements" to postgres, anon, authenticated, service_role;
